import React, {Component, Fragment} from 'react';
import {Field, reduxForm, formValueSelector} from 'redux-form';
import InputRange from 'react-input-range';
import ReactTooltip from 'react-tooltip';
import {connect} from 'react-redux';
import {updateProduct} from '../../actions/product';
import {getProductById} from '../../actions/product';
import {getIndustryList} from '../../actions/industry';
import {downloadToken} from '../../actions/download';
import {getServiceList} from '../../actions/service';
import {getCounties, getAllState} from '../../actions/statesCounties';

import Subheader from '../general/Subheader';
import AnimatedCard from '../general/AnimatedCard';
import * as validation from '../../_utils/validate';
import Translate from 'react-translate-component'
import {findId, getId, extractIdForName, extractIdCounty} from '../../_utils/misc';

import {
    inputField,
    dropDownField,
    inputSlider,
    renderDropzoneField,
    radioButton,
    renderMultiselect
} from '../../_formFields';


const credits = [
    {
        "id": 1,
        "name": "Creditreform"
    },
    {
        "id": 2,
        "name": "Fitch"
    },
    {
        "id": 3,
        "name": "Moody's"
    },
    {
        "id": 4,
        "name": "Euler Hermes"
    },
    {
        "id": 5,
        "name": "Standard & Poors"
    },
    {
        "id": 6,
        "name": "Bank/Andere"
    }
]

class EditProduct extends Component {
    state = {
        cities: [],
        ratings: [],
        rating_value: [],
        grade: '',
        cityNames: [],
        services: [],
        industries: [],
        states: [],
        statesWithId: [],
        value: {min: 15, max: 50},
        existing_file_id: []
    };

    componentDidMount() {
        if (!this.props.location.state) {
            // Redirect to list page if therer is no id of product to be fetched availabel
            return this.props.history.push('/products')
        }
        this.props.getAllState();
        this.props.getProductById(this.props.location.state.id)
        this.props.getIndustryList();
        this.props.getServiceList();
        this.props.getCounties();
    }

    componentDidUpdate(prevProps, prevState) {
        if (this.props.initialValues !== prevProps.initialValues) {
            let id = findId(this.props.initialValues.states, this.state.statesWithId);
            this.props.getCounties(id);
        }
        if (prevProps.allStates !== this.props.allStates) {
            this.setState({states: this.props.allStates.list, statesWithId: this.props.allStates.all})
        }
        if (this.props.states !== prevProps.states) {
            this.props.getCounties(extractIdForName(this.props.states, this.state.statesWithId))
        }
        ;
        if (this.props.service !== prevProps.service) {
            this.setState({services: this.props.service})
        }
        ;
        if (this.props.industry !== prevProps.industry) {
            this.setState({industries: this.props.industry})
        }
        if (this.props.county !== prevProps.county) {
            this.setState({
                cities: this.props.county.list,
                cityNames: this.props.county.name
            })
        }
        if (this.props.initialValues !== prevProps.initialValues) {
            var existingFile = [];
            if (Array.isArray(this.props.initialValues.documents)) {
                this.props.initialValues.documents.forEach((doc) => {
                    existingFile.push(doc.id)
                })
            }
            this.setState({existing_file_id: existingFile})
            this.setState({
                value: {
                    min: this.props.initialValues.min_time_duration,
                    max: this.props.initialValues.max_time_duration
                }
            })
        }
    }

    showFiles = files => {
        if (files.lenght === 0) {
            return <span>No Attachments Available</span>
        } else {
            return files.map((file, index) => {
                return (
                    <div className="file mb-2">
                        <span className="file-name">{file.file_name}</span>
                        {/* <span className="ml-4 file-size">FileType: {file.file_type}</span> */}
                        <span className='btn btn-link'
                              onClick={() => this.props.downloadToken(file.path, file.file_name, file.type)}><Translate
                            content='button.download'/></span>
                    </div>
                )

            })
        }
    }
    onSubmit = formProps => {

        // To delete duplicate keys while adding credit ratings
        const filteredArr = this.state.rating_value.reverse().reduce((acc, current) => {
            const x = acc.find(item => item.id === current.id);
            if (!x) {
                return acc.concat([current]);
            } else {
                return acc;
            }
        }, []);
        this.setState({rating_value: filteredArr});
        if (formProps.undefined[0] === 'Select All') {
            formProps.industry_id = getId(this.props.industry.list, null);
        } else {
            formProps.industry_id = getId(this.props.industry.list, formProps.undefined, this.props.language);
        }

        formProps.ratings = this.state.rating_value;
        if (formProps.County[0] === 'Select All') {
            formProps.county_ids = extractIdCounty(null, this.state.cities);
        } else {
            formProps.county_ids = extractIdCounty(formProps.County, this.state.cities);
        }
        if (formProps.states === 'Select All') {
            formProps.state_ids = extractIdForName(null, this.state.statesWithId);

        } else {
            formProps.state_ids = extractIdForName(formProps.states, this.state.statesWithId);
        }
        formProps.min_time_duration = this.state.value.min;
        formProps.max_time_duration = this.state.value.max;
        // console.log(formProps);
        this.props.updateProduct(formProps, this.props.location.state.id, () => this.props.history.push({
            pathname: '/product',
            state: {id: this.props.location.state.id}
        }))
    };

    creditRatings = (credits) => {
        return credits.map((credit, index) => {
            return (
                // <div className="rating d-flex justify-content-between align-content-center flex-wrap mt-3">
                <div className="rating-item">
                    <div className="col-9">
                        {/* <label>Ratingagentur</label> */}
                        <Translate content='label.Ratingagentur' component="label"/>
                        <br/>
                        <input className="mr-2" type="checkbox" name={credit.id} value=""
                               onChange={() => this.setState({ratings: [...this.state.ratings, credit.id]})}
                        />{credit.name}
                    </div>
                    <div className="col-9">
                        {/* <label>Kreditrating</label> */}
                        <Translate content='label.Kreditrating' component="label"/>
                        <br/>
                        <input
                            type="text" name={`rating_value[${credit.id}]`}
                            onChange={(e) => this.setState({
                                rating_value: [...this.state.rating_value, {
                                    rating_id: credit.id,
                                    value: e.target.value
                                }]
                            })
                            }
                            className="col-3 form-control text-center"
                        /></div>
                </div>
                // </div>
            )
        })

    }

    render() {
        const {
            handleSubmit,
            min_creditValue,
            credit,
            max_credit_amount,
            min_sales_creditor,
            files
        } = this.props;

        return (
            <Fragment>
                <Subheader heading={<Translate content='button.edit'/>}/>
                <AnimatedCard className="content-body">
                    <form className="form-signup" onSubmit={handleSubmit(this.onSubmit)}>
                        <div className="row mt-4">
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='product'>
                                        <strong> <Translate content='label.producttitle' data-tip
                                                            data-for='product'/></strong>
                                    </label>
                                    <ReactTooltip id='product' type='info'>
                                        <Translate content='tooltip.productName'/>
                                    </ReactTooltip>
                                    <Field
                                        name="product_title"
                                        type="text"
                                        component={inputField}
                                        // label={<Translate content='label.producttitle' />}
                                        className="form-control"
                                        validate={validation.required}
                                    />
                                </div>
                            </div>
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='state'>
                                        <strong> <Translate content='label.state' data-tip data-for='state'/></strong>
                                    </label>
                                    <ReactTooltip id='state' type='info'>
                                        <Translate content='tooltip.states'/>
                                    </ReactTooltip>
                                    <Field
                                        name="states"
                                        component={renderMultiselect}
                                        data={this.state.states}
                                        // label={<Translate content='label.state' />}
                                        validate={validation.required}
                                        placeholder={<Translate content='placeholder.select'/>}
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="row mt-4">
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='service'>
                                        <strong> <Translate content='label.service' data-tip
                                                            data-for='service'/></strong>
                                    </label>
                                    <ReactTooltip id='service' type='info'>
                                        <Translate content='tooltip.service'/>
                                    </ReactTooltip>
                                    <Field
                                        name="services"
                                        component={dropDownField}
                                        options={this.state.services[`${this.props.language}`]}
                                        // label={<Translate content='label.service' />}
                                        validate={validation.required}
                                        placeholder={<Translate content='placeholder.select'/>}
                                    />
                                </div>
                            </div>
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='county'>
                                        <strong> <Translate content='label.county' data-tip
                                                            data-for='service'/></strong>
                                    </label>
                                    <ReactTooltip id='county' type='info'>
                                        <Translate content='tooltip.county'/>
                                    </ReactTooltip>
                                    <Field
                                        name="County"
                                        component={renderMultiselect}
                                        data={this.state.cityNames}
                                        // label={<Translate content='label.county' />}
                                        // validate={validation.required}
                                        placeholder="select tags"
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="row mt-4">
                            <div className="col-12 col-sm-12 col-md-6">
                                <label htmlFor="amount" data-tip data-for='industry'>
                                    <strong> <Translate content='label.industries'/></strong>
                                </label>
                                <ReactTooltip id='industry' type='info'>
                                    <Translate content='tooltip.industry'/>
                                </ReactTooltip>
                                <Field
                                    component={renderMultiselect}
                                    // label={<Translate content='label.industries' />}
                                    data={this.state.industries.names ? this.state.industries.names[`${this.props.language}`] : []}
                                    className="form-group"

                                />
                            </div>

                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='time-duration'>
                                        <strong><Translate content='label.timeduration'/></strong>
                                    </label>
                                    <div className="d-flex align-items-center">
                                        <ReactTooltip id='time-duration' type='info'>
                                            <Translate content='tooltip.timeDuration'/>
                                        </ReactTooltip>
                                        <div className="d-flex align-items-center">
                                            <input
                                                className="form-control"
                                                type="text"
                                                id="mincredit-amount-value"
                                                // value={time_duration}
                                                value={this.state.value.min}
                                                validate={validation.required}
                                                placeholder="3 Monate"
                                            />&nbsp;&nbsp;
                                            <InputRange
                                                maxValue={60}
                                                minValue={12}
                                                value={this.state.value}
                                                onChange={value => this.setState({value})}/>
                                            {/* <div className="col-12 col-sm-12 col-md-6"> */}
                                            &nbsp;&nbsp;<input
                                            className="form-control"
                                            type="text"
                                            id="mincredit-amount-value"
                                            // value={time_duration}
                                            value={this.state.value.max}
                                            validate={validation.required}
                                            placeholder="3 Monate"
                                        />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="row mt-4">
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='min-credit'>
                                        <strong> <Translate content='label.mincredit'/></strong>
                                    </label>
                                    <ReactTooltip id='min-credit' type='info'>
                                        <Translate content='tooltip.minCreditAmount'/>
                                    </ReactTooltip>
                                    <div className="d-flex align-items-center">
                                        <Field
                                            name="min_credit_amount"
                                            type="range"
                                            component={inputSlider}
                                            // label={<Translate content='label.mincredit' />}
                                            id="mincredit-amount"
                                            validate={validation.required}
                                            min="250000"
                                            max="5000000"

                                        />
                                        €<input
                                        className="form-control"
                                        type="text"
                                        id="mincredit-amount-value"
                                        value={min_creditValue}
                                        validate={validation.required}
                                        placeholder="€0.0"
                                    />
                                    </div>
                                </div>
                            </div>
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <label htmlFor="amount" data-tip data-for='max-credit'>
                                        <strong> <Translate content='label.maxcredit'/></strong>
                                    </label>
                                    <ReactTooltip id='max-credit' type='info'>
                                        <Translate content='tooltip.maxCreditAmount'/>
                                    </ReactTooltip>
                                    <div className="form-group-ranger">
                                        <Field
                                            name="max_credit_amount"
                                            type="range"
                                            component={inputSlider}
                                            // label={<Translate content='label.maxcredit' />}
                                            id="mincredit-amount"
                                            readOnly
                                            validate={validation.required}
                                            min="250000"
                                            max="5000000"
                                        />
                                        €<input
                                        className="form-control"
                                        type="text"
                                        id="amount"
                                        value={max_credit_amount}
                                        validate={validation.required}
                                        placeholder="€0.0"
                                    />
                                    </div>
                                </div>
                            </div>
                        </div>


                        <div className="row mt-4">
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    {/* <div className="row align-items-end"> */}
                                    <label htmlFor="amount" data-tip data-for='min-sales'>
                                        <strong> <Translate content='label.minimumsales'/></strong>
                                    </label>
                                    <ReactTooltip id='min-sales' type='info'>
                                        <Translate content='tooltip.minSales'/>
                                    </ReactTooltip>
                                    <div className="form-group-ranger">
                                        <Field
                                            name="min_sales_creditor"
                                            type="range"
                                            component={inputSlider}
                                            id="mincredit-amount"
                                            validate={validation.required}
                                            min="0"
                                            max="50000000"

                                        />
                                        €<input
                                        className="form-control"
                                        type="text"
                                        id="mincredit-amount-value"
                                        value={min_sales_creditor}
                                        validate={validation.required}
                                        placeholder="€0.0"
                                    />
                                    </div>
                                </div>
                            </div>
                            <div className="col-12 col-sm-12 col-md-6">
                                <div className="form-group">
                                    <strong>
                                        <Translate content='label.Sicherheiten' component='label' className="d-block"
                                                   data-tip data-for='collateral'/>
                                    </strong>
                                    <ReactTooltip id='collatoral' type='info'>
                                        <Translate content='tooltip.collateral'/>
                                    </ReactTooltip>
                                    <div className="form-check form-check-inline">
                                        <Field
                                            component={radioButton}
                                            value="true"
                                            name="collatoral"
                                            className="form-check-input"
                                            id="credit"
                                            checked={this.props.initialValues.collatoral === 1 ? true : false}
                                        />
                                        <Translate content='label.yes' component='label' className="form-check-label"
                                                   htmlFor="rating-credit-yes"/>
                                    </div>
                                    <div className="form-check form-check-inline">
                                        <Field
                                            component={radioButton}
                                            value="false"
                                            name="collatoral"
                                            className="form-check-input"
                                            id="credit"
                                            checked={this.props.initialValues.collatoral === 0 ? true : false}
                                        />
                                        <Translate content='label.no' component='label' className="form-check-label"
                                                   htmlFor="rating-credit-no"/>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="row mt-4">
                            <div className="col">
                                <div className="form-group">
                                    <strong><Translate content='label.rating' component="label" className="d-block"
                                                       data-tip data-for='rating'/></strong>
                                    <ReactTooltip id='rating' type='info'>
                                        <Translate content='tooltip.rating'/>
                                    </ReactTooltip>
                                    <div className="form-check form-check-inline">
                                        <Field
                                            type="radio"
                                            component={radioButton}
                                            value="true"
                                            name="credit"
                                            className="form-check-input"
                                            id="credit"
                                        />
                                        <Translate content='label.yes' component='label' className="form-check-label"
                                                   htmlFor="rating-credit-yes"/>
                                    </div>
                                    <div className="form-check form-check-inline">
                                        <Field
                                            type="radio"
                                            component={radioButton}
                                            value="false"
                                            name="credit"
                                            className="form-check-input"
                                            id="credit"
                                        />
                                        <Translate content='label.no' component='label' className="form-check-label"
                                                   htmlFor="rating-credit-no"/>
                                    </div>
                                </div>
                            </div>
                            {credit === 'true' ? (
                                <div
                                    className="rating d-flex justify-content-between align-content-center flex-wrap mt-3">
                                    <div className="row">{this.creditRatings(credits)}</div>
                                </div>
                                // </div>
                            ) : null}
                        </div>
                        <div className="row mt-4">
                            <div className="col">
                                <div className="form-group">
                                    <Translate content='label.fileupload' component="label" data-tip
                                               data-for='files'/>
                                    <ReactTooltip id='files' type='info'>
                                        <Translate content='tooltip.documents'/>
                                    </ReactTooltip>
                                    <Field
                                        name="files"
                                        component={renderDropzoneField}
                                        type="file"
                                        className="file-uploader file-uploader--small dropzone"
                                    />
                                    {files ? <strong>Filename: {files[0].name}</strong> : null}
                                </div>
                                {this.props.initialValues.documents ? this.showFiles(this.props.initialValues.documents) : null}
                            </div>
                        </div>

                        {this.props.errMsg ? (
                            <li className="d-flex mb-1">
                                <img src={`${process.env.PUBLIC_URL}/assets/img/icons/bx-check-circle.svg`} alt="alt"/>
                                <span className="pl-2 green-text">{this.props.errMsg}</span>
                            </li>

                        ) : null}
                        <div className="row mt-4">
                            <div className="col">
                                <Translate content='button.submit' component="button"
                                           className="btn btn-primary btn-form" type="submit"/>
                            </div>
                        </div>
                    </form>
                </AnimatedCard>
            </Fragment>
        );
    }
}

function mapStateToProps(state) {
    return {
        errMsg: state.errors,
        industry: state.industryList,
        service: state.service,
        language: state.language,
        initialValues: state.singleProduct.product,
        allStates: state.allStates,
        county: state.county
    };
}

EditProduct = reduxForm({
    form: 'editProduct',
    enableReinitialize: true
})(EditProduct);

const selector = formValueSelector('editProduct');
EditProduct = connect(state => {
    const states = selector(state, 'states');
    const credit = selector(state, 'credit');
    const min_creditValue = selector(state, 'min_credit_amount');
    const max_credit_amount = selector(state, 'max_credit_amount');
    const min_sales_creditor = selector(state, 'min_sales_creditor')
    const files = selector(state, 'files')
    return {
        states,
        credit,
        min_creditValue,
        max_credit_amount,
        min_sales_creditor,
        files
    };
})(EditProduct);
export default connect(
    mapStateToProps,
    {updateProduct, getIndustryList, getServiceList, getProductById, downloadToken, getCounties, getAllState}
)(EditProduct);
